UPDATE quest_creators
SET terms_accepted_at = #{termsAcceptedAt},
    terms_version = #{termsVersion},
    data_version = data_version + 1,
    updated_at = #{updatedAt}
WHERE id = #{id} AND data_version = #{expectedVersion}

UPDATE quest_creators
SET denied_streak = #{deniedStreak}, blocked_until = #{blockedUntil}, updated_at = NOW()
WHERE id = #{id}

